# Simple shim around the documented Waveshare.battery.Battery API
# so that code can be type-checked and easily swapped when running on real HW.

class Battery:
    """Wrapper for Waveshare.battery.Battery (not used by current design)."""

    def __init__(self):
        # On real hardware, initialize ADC etc.
        pass

    def get_percentage(self) -> int:
        # Return dummy value for now.
        return 100

    def get_voltag(self) -> float:
        # NOTE: Name kept as specified in the prompt (get_voltag, not get_voltage).
        return 4.2

# Shim matching Waveshare.motor.Motor API.
# On real HW, this should wrap the actual motor driver.

class Motor:
    """Differential drive motor interface.

    Matches the API specified in the prompt.
    """

    def __init__(self):
        # Initialize GPIO / PWM here on real hardware.
        self._left_speed = 0
        self._right_speed = 0

    def backward(self, speed: int) -> None:
        self.set(-abs(speed), -abs(speed))

    def forward(self, speed: int) -> None:
        self.set(abs(speed), abs(speed))

    def left(self, speed: int) -> None:
        self.set(-abs(speed), abs(speed))

    def right(self, speed: int) -> None:
        self.set(abs(speed), -abs(speed))

    def set(self, left_speed: int, right_speed: int) -> None:
        """Set raw wheel speeds in range [-100, 100]."""
        self._left_speed = max(-100, min(100, int(left_speed)))
        self._right_speed = max(-100, min(100, int(right_speed)))
        # TODO: send values to actual hardware

    def stop(self) -> None:
        self.set(0, 0)

    @property
    def last_speeds(self):
        return self._left_speed, self._right_speed

